-- FetUre domain and demo taxonomy. Apply ONLY in a dedicated FetUre Supabase project.
-- Never seed fake user identities from the HTML concept.
create table if not exists public.feture_categories(id text primary key,title text not null,short_title text not null,icon text not null,accent_color text not null,position integer not null unique);
create table if not exists public.feture_interests(id text primary key,category_id text not null references public.feture_categories(id),title text not null,position integer not null,unique(category_id,position));
create table if not exists public.feture_tests(id text primary key,title text not null,description text not null,category_id text references public.feture_categories(id),question_count int not null check(question_count between 1 and 100));
create table if not exists public.feture_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',about text not null default '',dating_enabled boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.feture_interest_states(user_id uuid not null references auth.users(id) on delete cascade,interest_id text not null references public.feture_interests(id),status text not null check(status in ('unknown','curious','fantasy','want_to_try','experienced','soft_limit','hard_limit','not_interested')),intensity smallint check(intensity between 0 and 100),visibility text not null default 'private' check(visibility in ('private','public','granted')),updated_at timestamptz not null default now(),primary key(user_id,interest_id));
create table if not exists public.feture_test_responses(user_id uuid not null references auth.users(id) on delete cascade,test_id text not null references public.feture_tests(id),answers jsonb not null default '{}'::jsonb,taken_at timestamptz not null default now(),primary key(user_id,test_id));
create table if not exists public.feture_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(body)<=10000),audience text not null default 'private' check(audience in ('private','public','granted')),created_at timestamptz not null default now());
create table if not exists public.feture_profile_access(owner_id uuid not null references auth.users(id) on delete cascade,viewer_id uuid not null references auth.users(id) on delete cascade,scope text[] not null default '{}',expires_at timestamptz,revoked_at timestamptz,primary key(owner_id,viewer_id),check(owner_id<>viewer_id));
create table if not exists public.feture_dating_preferences(user_id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default false,preferences jsonb not null default '{}'::jsonb);
alter table public.feture_categories enable row level security;
alter table public.feture_interests enable row level security;
alter table public.feture_tests enable row level security;
alter table public.feture_profiles enable row level security;
alter table public.feture_interest_states enable row level security;
alter table public.feture_test_responses enable row level security;
alter table public.feture_posts enable row level security;
alter table public.feture_profile_access enable row level security;
alter table public.feture_dating_preferences enable row level security;
grant select on public.feture_categories,public.feture_interests,public.feture_tests to anon,authenticated;
grant select,insert,update,delete on public.feture_profiles,public.feture_interest_states,public.feture_test_responses,public.feture_posts,public.feture_profile_access,public.feture_dating_preferences to authenticated;
create policy "catalog_read_categories" on public.feture_categories for select to anon,authenticated using(true);
create policy "catalog_read_interests" on public.feture_interests for select to anon,authenticated using(true);
create policy "catalog_read_tests" on public.feture_tests for select to anon,authenticated using(true);
create policy "profiles_owner_select" on public.feture_profiles for select to authenticated using(((select auth.uid())=user_id));
create policy "profiles_owner_insert" on public.feture_profiles for insert to authenticated with check(((select auth.uid())=user_id));
create policy "profiles_owner_update" on public.feture_profiles for update to authenticated using(((select auth.uid())=user_id)) with check(((select auth.uid())=user_id));
create policy "profiles_owner_delete" on public.feture_profiles for delete to authenticated using(((select auth.uid())=user_id));
