create policy "interest_states_owner_delete" on public.feture_interest_states for delete to authenticated using(((select auth.uid())=user_id));
create policy "test_responses_owner_select" on public.feture_test_responses for select to authenticated using(((select auth.uid())=user_id));
create policy "test_responses_owner_insert" on public.feture_test_responses for insert to authenticated with check(((select auth.uid())=user_id));
create policy "test_responses_owner_update" on public.feture_test_responses for update to authenticated using(((select auth.uid())=user_id)) with check(((select auth.uid())=user_id));
create policy "test_responses_owner_delete" on public.feture_test_responses for delete to authenticated using(((select auth.uid())=user_id));
create policy "posts_owner_select" on public.feture_posts for select to authenticated using(((select auth.uid())=author_id));
create policy "posts_owner_insert" on public.feture_posts for insert to authenticated with check(((select auth.uid())=author_id));
create policy "posts_owner_update" on public.feture_posts for update to authenticated using(((select auth.uid())=author_id)) with check(((select auth.uid())=author_id));
create policy "posts_owner_delete" on public.feture_posts for delete to authenticated using(((select auth.uid())=author_id));
create policy "dating_preferences_owner_select" on public.feture_dating_preferences for select to authenticated using(((select auth.uid())=user_id));
create policy "dating_preferences_owner_insert" on public.feture_dating_preferences for insert to authenticated with check(((select auth.uid())=user_id));
create policy "dating_preferences_owner_update" on public.feture_dating_preferences for update to authenticated using(((select auth.uid())=user_id)) with check(((select auth.uid())=user_id));
create policy "dating_preferences_owner_delete" on public.feture_dating_preferences for delete to authenticated using(((select auth.uid())=user_id));
create policy "profile_access_owner_select" on public.feture_profile_access for select to authenticated using(((select auth.uid())=owner_id));
create policy "profile_access_owner_insert" on public.feture_profile_access for insert to authenticated with check(((select auth.uid())=owner_id));
create policy "profile_access_owner_update" on public.feture_profile_access for update to authenticated using(((select auth.uid())=owner_id)) with check(((select auth.uid())=owner_id));
create policy "profile_access_owner_delete" on public.feture_profile_access for delete to authenticated using(((select auth.uid())=owner_id));
